import { Connection, PublicKey, SystemProgram, Transaction } from '@solana/web3.js';
import { AnchorProvider, Program } from '@coral-xyz/anchor';
import BN from 'bn.js';

if (typeof window !== 'undefined') {
    window.BN = BN;
    window.Buffer = Buffer;
}

class BlockchainManager {
    constructor() {
        this.program = null;
        this.provider = null;
        this.wallet = null;
        this.playerAccount = null;
        this.gameStateAccount = null;
        this.isConnected = false;
        this.programId = '87zxn6W3crE9U2p8FjWp45oQ5rZ5TNBjU2oMzEv4m6tg';
    }

    async initialize() {
        try {
            if (typeof window !== 'undefined') {
                window.BN = BN;
                window.Buffer = Buffer;
            }
            
            await this.checkAndMigrateAccounts();
            
            const connection = new Connection('https://api.devnet.solana.com', 'confirmed');
            
            const wallet = await this.getWallet();
            if (!wallet) {
                throw new Error('Wallet not found');
            }

            if (!wallet.publicKey) {
                throw new Error('Wallet public key not found');
            }

            this.wallet = wallet;
            
            
            const phantomWallet = {
                publicKey: wallet.publicKey,
                signTransaction: async (tx) => {
                    if (wallet.signTransaction) {
                        return await wallet.signTransaction(tx);
                    } else {
                        return await window.solana.signTransaction(tx);
                    }
                },
                signAllTransactions: async (txs) => {
                    if (wallet.signAllTransactions) {
                        return await wallet.signAllTransactions(txs);
                    } else {
                        return await window.solana.signAllTransactions(txs);
                    }
                }
            };
            
            this.provider = new AnchorProvider(connection, phantomWallet, {
                preflightCommitment: 'confirmed',
                commitment: 'confirmed'
            });
            
            const idl = await this.loadIDL();
            const programId = new PublicKey(this.programId);
            
            
            this.program = new Program(idl, programId, this.provider);
            
            this.gameStateAccount = PublicKey.findProgramAddressSync(
                [Buffer.from('game_state')],
                programId
            )[0];
            
            this.playerAccount = PublicKey.findProgramAddressSync(
                [Buffer.from('player'), wallet.publicKey.toBuffer()],
                programId
            )[0];
            
            this.isConnected = true;
            return true;
        } catch (error) {
            return false;
        }
    }

    async getWallet() {
        if (window.solana && window.solana.isPhantom) {
            try {
                const response = await window.solana.connect();
                
                if (!response || !response.publicKey) {
                    throw new Error('Invalid wallet response - missing publicKey');
                }
                
                return response;
            } catch (error) {
                throw new Error('Failed to connect to Phantom wallet. Please try again.');
            }
        }
        
        const installMessage = `
🚨 SOLANA WALLET REQUIRED

To play this blockchain game, you need a Solana wallet:

📱 INSTALL PHANTOM WALLET:
1. Go to: https://phantom.app/
2. Click "Download" or "Add to Chrome"
3. Install the browser extension
4. Create a new wallet (save your 12-word seed phrase!)
5. Switch to "Devnet" in settings
6. Get test SOL from: https://faucet.solana.com/
7. Refresh this page and try again

💡 TIP: Solana wallets are different from MetaMask (which is for Ethereum)

After installation, the "Connect Wallet" button will work!
        `;
        
        alert(installMessage);
        throw new Error('Phantom wallet not found. Please install Phantom wallet.');
    }

    async loadIDL() {
        const idl = {
            version: "0.1.0",
            name: "dino_blockchain",
            address: "87zxn6W3crE9U2p8FjWp45oQ5rZ5TNBjU2oMzEv4m6tg",
            instructions: [
                {
                    name: "initializeGameState",
                    accounts: [
                        { name: "gameState", isMut: true, isSigner: false },
                        { name: "authority", isMut: true, isSigner: true },
                        { name: "systemProgram", isMut: false, isSigner: false }
                    ],
                    args: []
                },
                {
                    name: "registerPlayer",
                    accounts: [
                        { name: "player", isMut: true, isSigner: false },
                        { name: "usernameRegistry", isMut: true, isSigner: false },
                        { name: "gameState", isMut: true, isSigner: false },
                        { name: "authority", isMut: true, isSigner: true },
                        { name: "systemProgram", isMut: false, isSigner: false }
                    ],
                    args: [{ name: "username", type: "string" }]
                },
                {
                    name: "updateProfile",
                    accounts: [
                        { name: "player", isMut: true, isSigner: false },
                        { name: "newUsernameRegistry", isMut: true, isSigner: false },
                        { name: "authority", isMut: true, isSigner: true },
                        { name: "systemProgram", isMut: false, isSigner: false }
                    ],
                    args: [{ name: "newUsername", type: "string" }]
                },
                {
                    name: "submitScore",
                    accounts: [
                        { name: "player", isMut: true, isSigner: false },
                        { name: "gameState", isMut: true, isSigner: false },
                        { name: "authority", isMut: true, isSigner: true }
                    ],
                    args: [{ name: "score", type: "u64" }]
                }
            ],
            accounts: [
                {
                    name: "GameState",
                    type: {
                        kind: "struct",
                        fields: [
                            { name: "authority", type: "publicKey" },
                            { name: "totalPlayers", type: "u64" },
                            { name: "totalGames", type: "u64" }
                        ]
                    }
                },
                {
                    name: "Player",
                    type: {
                        kind: "struct",
                        fields: [
                            { name: "authority", type: "publicKey" },
                            { name: "username", type: "string" },
                            { name: "gamesPlayed", type: "u64" },
                            { name: "bestScore", type: "u64" },
                            { name: "totalScore", type: "u64" },
                            { name: "bestScoreTimestamp", type: "i64" },
                            { name: "gameHistory", type: { vec: { defined: "GameRecord" } } },
                            { name: "bump", type: "u8" }
                        ]
                    }
                },
                {
                    name: "UsernameRegistry",
                    type: {
                        kind: "struct",
                        fields: [
                            { name: "username", type: "string" },
                            { name: "player", type: "publicKey" },
                            { name: "bump", type: "u8" }
                        ]
                    }
                }
            ],
            types: [
                {
                    name: "GameRecord",
                    type: {
                        kind: "struct",
                        fields: [
                            { name: "score", type: "u64" },
                            { name: "timestamp", type: "i64" }
                        ]
                    }
                }
            ],
            events: [],
            errors: []
        };
        return idl;
    }

    async ensureGameStateInitialized() {
        try {
            
            const accountInfo = await this.provider.connection.getAccountInfo(this.gameStateAccount);
            
            if (!accountInfo) {
                await this.initializeGameState();
            } else {
                if (accountInfo.owner.toString() !== this.programId) {
                    await this.initializeGameState();
                } else {
                }
            }
        } catch (error) {
            throw error; // Re-throw to prevent registration with wrong game state
        }
    }

    async initializeGameState() {
        try {
            
            try {
                const tx = await this.program.methods
                    .initializeGameState()
                    .accounts({
                        gameState: this.gameStateAccount,
                        authority: this.wallet.publicKey,
                        systemProgram: SystemProgram.programId
                    })
                    .rpc();
                
                return tx;
            } catch (anchorError) {
                throw anchorError; // Don't fallback to manual approach
            }
        } catch (error) {
            throw error;
        }
    }

    async registerPlayer(username) {
        try {
            await this.ensureGameStateInitialized();
            
            const [usernameRegistryAccount] = PublicKey.findProgramAddressSync(
                [Buffer.from('username'), Buffer.from(username)],
                new PublicKey(this.programId)
            );
            
            const tx = await this.program.methods
                .registerPlayer(username)
                .accounts({
                    player: this.playerAccount,
                    usernameRegistry: usernameRegistryAccount,
                    gameState: this.gameStateAccount,
                    authority: this.wallet.publicKey,
                    systemProgram: SystemProgram.programId
                })
                .rpc();
            
            return tx;
        } catch (error) {
            if (error.message && error.message.includes('already been processed')) {
                
                try {
                    const currentPlayerData = await this.getPlayerData();
                    if (currentPlayerData && currentPlayerData.username === username) {
                        return 'duplicate_transaction_success';
                    }
                } catch (verifyError) {
                }
                
                return 'duplicate_transaction_success';
            }
            
            if (error.message && error.message.includes('already in use')) {
                throw new Error('Username is already taken. Please choose a different name.');
            }
            
            if (error.message && error.message.includes('custom program error: 0x0')) {
                throw new Error('Username is already taken. Please choose a different name.');
            }
            
            throw error;
        }
    }

    async updateProfile(newUsername) {
        try {
            const [newUsernameRegistryAccount] = PublicKey.findProgramAddressSync(
                [Buffer.from('username'), Buffer.from(newUsername)],
                new PublicKey(this.programId)
            );
            
            const tx = await this.program.methods
                .updateProfile(newUsername)
                .accounts({
                    player: this.playerAccount,
                    newUsernameRegistry: newUsernameRegistryAccount,
                    authority: this.wallet.publicKey,
                    systemProgram: SystemProgram.programId
                })
                .rpc();
            
            return tx;
        } catch (error) {
            if (error.message && error.message.includes('already been processed')) {
                
                try {
                    const currentPlayerData = await this.getPlayerData();
                    if (currentPlayerData && currentPlayerData.username === newUsername) {
                        return 'duplicate_transaction_success';
                    }
                } catch (verifyError) {
                }
                
                return 'duplicate_transaction_success';
            }
            
            throw error;
        }
    }

    async submitScore(score) {
        try {
            const scoreBN = new BN(Number(score) || 0, 10);
            
            const tx = await this.program.methods
                .submitScore(scoreBN)
                .accounts({
                    player: this.playerAccount,
                    gameState: this.gameStateAccount,
                    authority: this.wallet.publicKey
                })
                .rpc();
            
            
            return tx;
        } catch (error) {
            if (error.message && error.message.includes('ConstraintSeeds')) {
                localStorage.setItem('dino_needs_migration', 'true');
                throw new Error('Account structure changed. Please reconnect your wallet to recreate accounts.');
            }
            
            if (error.message && error.message.includes('already been processed')) {
                
                try {
                    const currentPlayerData = await this.getPlayerData();
                    if (currentPlayerData && currentPlayerData.bestScore) {
                        const currentBestScore = currentPlayerData.bestScore.toNumber();
                        if (currentBestScore >= score) {
                            return 'duplicate_transaction_success';
                        }
                    }
                } catch (verifyError) {
                }
                
                return 'duplicate_transaction_success';
            }
            
            throw error;
        }
    }

    async getGameHistory() {
        try {
            const playerData = await this.getPlayerData();
            
            if (playerData) {
                if (playerData.gameHistory && Array.isArray(playerData.gameHistory)) {
                    return playerData.gameHistory.map(game => ({
                        score: game.score ? game.score.toNumber() : game.score,
                        timestamp: game.timestamp ? game.timestamp.toNumber() : game.timestamp,
                        date: new Date((game.timestamp ? game.timestamp.toNumber() : game.timestamp) * 1000).toLocaleString('ru-RU')
                    }));
                } else {
                    return [];
                }
            }
            return [];
        } catch (error) {
            return [];
        }
    }

    async checkAndMigrateAccounts() {
        try {
            const needsMigration = localStorage.getItem('dino_needs_migration');
            if (needsMigration === 'true') {
                localStorage.removeItem('dino_needs_migration');
            }
        } catch (error) {
        }
    }

    async getPlayerData() {
        try {
            const playerData = await this.program.account.player.fetch(this.playerAccount);
            return playerData;
        } catch (error) {
            
            if (error.message && error.message.includes('ConstraintSeeds')) {
                localStorage.setItem('dino_needs_migration', 'true');
                throw new Error('Account structure changed. Please reconnect your wallet to recreate accounts.');
            }
            
            return null;
        }
    }

    async getGameState() {
        try {
            const gameState = await this.program.account.gameState.fetch(this.gameStateAccount);
            return gameState;
        } catch (error) {
            return null;
        }
    }

    async getLeaderboard() {
        try {
            const gameState = await this.getGameState();
            
            let players = [];
            
            try {
                const playerAccounts = await this.program.account.player.all();
                
                
                players = playerAccounts.map(account => {
                    try {
                        return {
                            name: account.account.username || 'Unknown',
                            gamesPlayed: account.account.gamesPlayed ? account.account.gamesPlayed.toNumber() : 0,
                            bestScore: account.account.bestScore ? account.account.bestScore.toNumber() : 0,
                            bestScoreTimestamp: account.account.bestScoreTimestamp ? account.account.bestScoreTimestamp.toNumber() : 0,
                            authority: account.account.authority ? account.account.authority.toString() : 'Unknown'
                        };
                    } catch (mapError) {
                        return null;
                    }
                }).filter(player => player !== null);
                
                players.sort((a, b) => b.bestScore - a.bestScore);
                
                
            } catch (accountError) {
                
                if (this.playerAccount) {
                    try {
                        const currentPlayer = await this.getPlayerData();
                        if (currentPlayer) {
                            players = [{
                                name: currentPlayer.username,
                                gamesPlayed: currentPlayer.gamesPlayed ? currentPlayer.gamesPlayed.toNumber() : 0,
                                bestScore: currentPlayer.bestScore ? currentPlayer.bestScore.toNumber() : 0,
                                authority: this.wallet.publicKey.toString()
                            }];
                        }
                    } catch (playerError) {
                    }
                }
            }
            
            return {
                totalPlayers: gameState?.totalPlayers || players.length,
                totalGames: gameState?.totalGames || 0,
                players: players
            };
        } catch (error) {
            return { 
                totalPlayers: 0, 
                totalGames: 0, 
                players: [] 
            };
        }
    }
}

export default BlockchainManager;